package org.firstinspires.ftc.teamcode.tuning;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

// Generated by refract-suite ftc-construct. The decisions of program 7's automatic steps, with no hardware in here:
// which P to fire the next recovery shot with, and which idle speed to keep. FlywheelTuner measures, this decides.
// Every number below is a test procedure setting (a policy), not a robot measurement.
public final class FlywheelAutoTune {
    private FlywheelAutoTune() {}

    public enum Verdict { NOT_COUNTED, STEADY, NOT_STEADY }

    // one recovery shot as FlywheelTuner measured it, and what the search made of it
    public static final class Trial {
        public final double p, dip, recoveryS, steadyS, overshoot, score;
        // overshoot in ready bands: how close it came to leaving the band again
        public double overshootBands;
        public final Verdict verdict;
        public final String why;
        // the P for the next shot (or the final one) and why
        public double nextP;
        public String nextWhy;

        Trial(double p, double dip, double recoveryS, double steadyS, double overshoot, Verdict verdict, double score, String why) {
            this.p = p;
            this.dip = dip;
            this.recoveryS = recoveryS;
            this.steadyS = steadyS;
            this.overshoot = overshoot;
            this.verdict = verdict;
            this.score = score;
            this.why = why;
        }

        public String line() {
            String steady = verdict == Verdict.NOT_COUNTED ? "not counted"
                    : steadyS < 0 ? "not steady in 2 s" : String.format(Locale.US, "steady after %.2f s", steadyS);
            return String.format(Locale.US, "P %.3f: %s, drop %.0f, past the target %.0f", p, steady, dip, overshoot);
        }
    }

    // The P search of the recovery step. P only: F comes from the top speed, I stays P / 10, D stays 0.
    // What counts is how soon after a shot the wheel is back inside the ready band and stays there (steadyS): that
    // is when the next element can go. It is measured, not assumed to get better or worse with P (on the simulator
    // it is better at both ends of the range than in the middle), so the search does not climb until a wobble:
    //   grid    the start P x 1, 2, 4, 8, 16, 32 (and x 0.5 when x 1 is the best of those)
    //   refine  x / sqrt 2 and x sqrt 2 around the best
    //   extend  x 64 once, when x 32 was clearly better than x 16 (the hard ceiling)
    //   check   the best P once more, until the best has two shots (a P whose check is slower drops back)
    // Each P counts with its WORST shot (a P that is quick only sometimes is not quick). Best = the shortest worst
    // steadyS; within the tie (the spread of repeated shots, 0.05 to 0.25 s) the one that overshoots least wins, then the
    // softer one. On the simulator the noise is large near the band edge, so the margin decides most ties.
    public static final class PSearch {
        public static final double[] GRID = {1, 2, 4, 8, 16, 32};
        public static final double LOW = 0.5, HIGH = 32;
        // when x32 is clearly better than x16, x64 is tried once; never stronger than this
        public static final double CEILING = 64;
        // steady times within the tie of each other count as equal: the spread of repeated shots of the same P, kept
        // between TIE_MIN_S and TIE_MAX_S (TIE_MIN_S until a P has been fired twice)
        public static final double TIE_MIN_S = 0.05, TIE_MAX_S = 0.25;
        public static final int MAX_SHOTS = 12, MAX_CHECKS = 3;
        // overshoots within this many ready bands of each other count as equal
        public static final double TIE_BANDS = 0.1;
        // a drop this many times the usual one = two elements went at once
        public static final double DOUBLE_DIP = 1.8;
        // the score of a shot after which the wheel never stayed in the band
        public static final double NOT_STEADY_S = 3.0;

        private enum Phase { GRID, REFINE, CHECK, DONE }

        private static final class State {
            Phase phase = Phase.GRID;
            List<Double> queue = new ArrayList<>();
            // per P (as a multiple of the start P): {score, overshoot in ready bands} of each counted shot
            Map<Double, List<double[]>> scores = new LinkedHashMap<>();
            double m = 1, finalP = Double.NaN;
            int counted, checks;
            String note = "";

            State copy() {
                State c = new State();
                c.phase = phase;
                c.queue = new ArrayList<>(queue);
                for (Map.Entry<Double, List<double[]>> e : scores.entrySet()) c.scores.put(e.getKey(), new ArrayList<>(e.getValue()));
                c.m = m;
                c.finalP = finalP;
                c.counted = counted;
                c.checks = checks;
                c.note = note;
                return c;
            }
        }

        private final double p0;
        private State s = new State(), before = null;
        private Trial pending = null;
        private final List<Trial> trials = new ArrayList<>();
        private final List<Double> dips = new ArrayList<>();

        public PSearch(double p0) {
            this.p0 = p0;
            for (int i = 1; i < GRID.length; i++) s.queue.add(GRID[i]);
            s.m = GRID[0];
        }

        // the P to fire the next shot with
        public double p() {
            return p0 * s.m;
        }

        public boolean done() {
            return s.phase == Phase.DONE;
        }

        public double finalP() {
            return s.finalP;
        }

        // why it finished the way it did ("" when there is nothing to add)
        public String note() {
            return s.note;
        }

        public int counted() {
            return s.counted;
        }

        // about how many shots the whole search takes
        public static int planned() {
            return GRID.length + 3;
        }

        public List<Trial> trials() {
            return Collections.unmodifiableList(trials);
        }

        // A shot just fired at p(). Returns what it made of it; nothing is kept until accept() (reject() drops it).
        // recoveryS < 0 = never back in the band; steadyS < 0 = never back in the band to stay.
        public Trial offer(double dip, double recoveryS, double steadyS, double overshoot, double band) {
            if (pending != null) reject();
            before = s.copy();
            Verdict v;
            String why;
            if (dip <= band) {
                v = Verdict.NOT_COUNTED;
                why = "the wheel hardly slowed, so no element reached it: load one and fire again";
            } else if (!dips.isEmpty() && dip > DOUBLE_DIP * median(dips)) {
                v = Verdict.NOT_COUNTED;
                why = "the speed dropped about twice as much as before: two elements went at once. Load ONE and fire again";
            } else if (steadyS < 0) {
                v = Verdict.NOT_STEADY;
                why = recoveryS < 0 ? "not back to speed within 2 s" : "back to speed, but it keeps swinging out of the ready band";
            } else {
                v = Verdict.STEADY;
                why = steadyS - recoveryS > 0.2 && recoveryS >= 0
                        ? String.format(Locale.US, "back at %.2f s, swung out again, steady from %.2f s", recoveryS, steadyS)
                        : String.format(Locale.US, "back to speed and steady after %.2f s", steadyS);
            }
            double score = v == Verdict.STEADY ? steadyS : NOT_STEADY_S;
            pending = new Trial(p(), dip, recoveryS, steadyS, overshoot, v, score, why);
            pending.overshootBands = band > 0 ? Math.max(0, overshoot) / band : 0;
            pending.nextP = decide(pending);
            return pending;
        }

        public void accept() {
            if (pending == null) return;
            trials.add(pending);
            if (pending.verdict != Verdict.NOT_COUNTED) dips.add(pending.dip);
            pending = null;
            before = null;
        }

        public void reject() {
            if (pending == null) return;
            s = before;
            pending = null;
            before = null;
        }

        // the driver stops the search: keep the best so far
        public void stop() {
            accept();
            if (done()) return;
            Double best = best();
            if (best == null) finish(p(), "stopped by the driver before any shot");
            else finish(p0 * best, "stopped by the driver: the best P so far" + (s.phase == Phase.CHECK ? "" : ", not checked again"));
        }

        private double decide(Trial t) {
            if (t.verdict == Verdict.NOT_COUNTED) {
                t.nextWhy = "the same P again";
                return p();
            }
            s.counted++;
            List<double[]> list = s.scores.get(s.m);
            if (list == null) {
                list = new ArrayList<>();
                s.scores.put(s.m, list);
            }
            list.add(new double[]{t.score, t.overshootBands});
            if (s.counted >= MAX_SHOTS) return end(MAX_SHOTS + " shots: stopped with the best P so far");
            switch (s.phase) {
                case GRID:
                    if (s.queue.isEmpty()) {
                        Double best = best();
                        if (best != null && best == 1 && !s.scores.containsKey(LOW)) {
                            s.queue.add(LOW);
                            return next(Phase.GRID, "the start P was the best so far: try half of it too");
                        }
                        if (best != null && best == HIGH && !s.scores.containsKey(CEILING) && s.scores.containsKey(HIGH / 2)
                                && worst(HIGH) < worst(HIGH / 2) - tie()) {
                            s.queue.add(CEILING);
                            return next(Phase.GRID, "the strongest P on the list was clearly the best: try twice as strong once");
                        }
                        return refine();
                    }
                    return next(Phase.GRID, "the next P on the list (start P x 1, 2, 4, 8, 16, 32)");
                case REFINE:
                    if (!s.queue.isEmpty()) return next(Phase.REFINE, "the other side of the best");
                    return check();
                case CHECK:
                    s.checks++;
                    Double best = best();
                    if (best != null && s.scores.get(best).size() < 2 && s.checks < MAX_CHECKS) {
                        s.m = best;
                        return say("the check was slower, so this P drops back: check the new best once more");
                    }
                    return end(best != null && s.scores.get(best).size() < 2 ? "the best P has only one shot (checks used up)" : "");
                default:
                    return p();
            }
        }

        // the best P (as a multiple of the start P): the shortest worst score; within TIE_S the smaller worst overshoot,
        // within TIE_BANDS of that the softer P
        private Double best() {
            Double bestM = null;
            double bestScore = Double.POSITIVE_INFINITY, bestOver = Double.POSITIVE_INFINITY;
            for (Map.Entry<Double, List<double[]>> e : s.scores.entrySet()) {
                double worst = 0, over = 0;
                for (double[] v : e.getValue()) {
                    worst = Math.max(worst, v[0]);
                    over = Math.max(over, v[1]);
                }
                boolean better;
                double tie = tie();
                if (bestM == null || worst < bestScore - tie) better = true;
                else if (worst > bestScore + tie) better = false;
                else if (over < bestOver - TIE_BANDS) better = true;
                else better = over <= bestOver + TIE_BANDS && e.getKey() < bestM;
                if (better) {
                    bestM = e.getKey();
                    bestScore = worst;
                    bestOver = over;
                }
            }
            return bestScore >= NOT_STEADY_S ? null : bestM;
        }

        // the worst score of a P (NOT_STEADY_S if it was never fired)
        private double worst(double m) {
            List<double[]> l = s.scores.get(m);
            if (l == null) return NOT_STEADY_S;
            double w = 0;
            for (double[] v : l) w = Math.max(w, v[0]);
            return w;
        }

        // how much two shots of the same P differ (the median over the P values fired more than once, steady shots only)
        public double tie() {
            List<Double> spreads = new ArrayList<>();
            for (List<double[]> l : s.scores.values()) {
                double lo = Double.POSITIVE_INFINITY, hi = Double.NEGATIVE_INFINITY;
                int n = 0;
                for (double[] v : l) {
                    if (v[0] >= NOT_STEADY_S) continue;
                    lo = Math.min(lo, v[0]);
                    hi = Math.max(hi, v[0]);
                    n++;
                }
                if (n >= 2) spreads.add(hi - lo);
            }
            if (spreads.isEmpty()) return TIE_MIN_S;
            return Math.max(TIE_MIN_S, Math.min(TIE_MAX_S, median(spreads)));
        }

        private double refine() {
            Double best = best();
            if (best == null) return end("never steady within 2 s at any P tried: recovery is limited by F, the feed or the battery, not by P");
            s.queue.clear();
            for (double m : new double[]{best / Math.sqrt(2), best * Math.sqrt(2)}) {
                if (m >= LOW - 1e-9 && m <= CEILING + 1e-9 && !s.scores.containsKey(m)) s.queue.add(m);
            }
            if (s.queue.isEmpty()) return check();
            return next(Phase.REFINE, String.format(Locale.US, "the best so far is %.3f: try just below and just above it", p0 * best));
        }

        private double check() {
            Double best = best();
            if (best == null) return end("never steady within 2 s at any P tried: recovery is limited by F, the feed or the battery, not by P");
            s.phase = Phase.CHECK;
            s.m = best;
            return say("the best P once more, to check it");
        }

        private double next(Phase phase, String why) {
            s.phase = phase;
            s.m = s.queue.remove(0);
            return say(why);
        }

        private double say(String why) {
            if (pending != null) pending.nextWhy = why;
            return p();
        }

        private double end(String note) {
            Double best = best();
            if (best == null) {
                finish(p0, note.isEmpty() ? "never steady within 2 s at any P tried: kept the start P" : note);
            } else {
                // the best at the strong end of the range: a stronger P was not tried, it may be quicker still
                String edge = best >= CEILING - 1e-9 ? "the best was the strongest P this step tries (" + Math.round(CEILING) + " x the start P)" : "";
                finish(p0 * best, note.isEmpty() ? edge : edge.isEmpty() ? note : note + "; " + edge);
            }
            return s.finalP;
        }

        private void finish(double p, String note) {
            s.phase = Phase.DONE;
            s.finalP = p;
            s.note = note;
            if (pending != null) pending.nextWhy = note.isEmpty() ? "done: the best P, checked" : note;
        }
    }

    // Idle speed: the lowest one whose spin-up to the shot speed is within IDLE_SLACK (or IDLE_SLACK_S) of the best of
    // the allowed candidates. fractions ascending; tUp in seconds (the cap value when it never got there).
    public static final double IDLE_SLACK = 0.15, IDLE_SLACK_S = 0.1;

    public static int chooseIdle(double[] fractions, double[] tUp, double capFraction) {
        double best = Double.POSITIVE_INFINITY;
        for (int i = 0; i < fractions.length; i++) if (fractions[i] <= capFraction + 1e-9) best = Math.min(best, tUp[i]);
        double limit = Math.max(best * (1 + IDLE_SLACK), best + IDLE_SLACK_S);
        for (int i = 0; i < fractions.length; i++) if (fractions[i] <= capFraction + 1e-9 && tUp[i] <= limit) return i;
        return 0;
    }

    private static double median(List<Double> values) {
        List<Double> v = new ArrayList<>(values);
        Collections.sort(v);
        int n = v.size();
        return n % 2 == 1 ? v.get(n / 2) : (v.get(n / 2 - 1) + v.get(n / 2)) / 2;
    }
}
